import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# A simple custom CUDA kernel for elementwise ReLU
relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto out = torch::zeros_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;
    relu_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

relu_cpp_source = r"""
torch::Tensor relu_cuda(torch::Tensor input);
"""

# Compile the inline CUDA code for ReLU
relu_extension = load_inline(
    name="custom_relu_extension",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_source,
    functions=["relu_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that uses nn.ConvTranspose2d and a custom CUDA kernel (ReLU).
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        output_padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        # Use the standard ConvTranspose2d module
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            dilation=dilation,
            groups=groups,
            bias=bias
        )
        # Reference to our custom ReLU function
        self.custom_relu = relu_extension

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Perform standard transposed convolution
        x = self.conv_transpose2d(x)
        # Apply custom ReLU kernel
        x = self.custom_relu.relu_cuda(x)
        return x
